// Relative feature-cost estimate, not a benchmark or a promised frame rate.
export function sceneComplexity(preset){
 const p=typeof preset==='string'?SCENE_PRESETS.find(scene=>scene.id===preset):preset;
 const s={...DEFAULTS,...p?.patch},objects=p?.objects||[];
 const score=Math.min(100,Math.round(8+(s.blackHole?15:0)+(s.binary?18:0)+(s.disk?10:0)+(s.jets?6:0)+(s.grid?7:0)+(s.nebula?7:0)+(s.bridge?25:0)+(s.warp?14:0)+(s.gravitationalWaves?4:0)+(s.bridgeMode==='crossed'?12:0)+objects.reduce((n,o)=>n+(['shuttle','iss','habitat','classicEnterprise','heritageShuttle','enterprise','astronaut'].includes(o.type)?8:['ring','belt'].includes(o.type)?5:3),0)));
 return {score,label:score<30?'Light':score<55?'Moderate':'Heavy',reason:'Relative scene complexity; quality, view, and device determine actual frame rate.'};
}
for(const scene of SCENE_PRESETS)scene.complexity=sceneComplexity(scene);

// Share compact-body names across the tree, camera, map and projected labels.
export function holeDisplayName(state,index=0,preset){
 const named=index?(state.secondaryName||preset?.secondaryName):(state.primaryName||preset?.primaryName);
 return named||`${(index?state.secondaryWhiteHole:state.whiteHole)?'White':'Black'} hole ${index?'B':'A'}`;
}
